let e2eResult;
try {
  const browserPluginRoot = process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
  if (!browserPluginRoot) throw new Error('Browser plugin root is unavailable in the node_repl host');
  const { join } = await import('node:path');
  const { pathToFileURL } = await import('node:url');
  const browserClientUrl = pathToFileURL(join(browserPluginRoot, 'scripts', 'browser-client.mjs')).href;
  const { setupBrowserRuntime } = await import(browserClientUrl);
  await setupBrowserRuntime({ globals: globalThis });
  const browser = await agent.browsers.get('iab');
  const tab = await browser.tabs.new();
  await tab.goto(new URL('/keys', '{{browserFixtureUrl}}').href);
  let inputFocused = false;
  for (let attempt = 0; attempt < 100 && !inputFocused; attempt += 1) {
    inputFocused = await tab.playwright.evaluate(() => { const input = document.getElementById('name'); input?.focus(); return input !== null && document.activeElement === input; });
    if (!inputFocused) await new Promise((resolve) => setTimeout(resolve, 100));
  }
  if (!inputFocused) throw new Error('keypress fixture input never received page focus');
  let gateOpen = false;
  for (let attempt = 0; attempt < 300 && !gateOpen; attempt += 1) {
    gateOpen = await tab.playwright.evaluate(() => window.__e2eGate === true);
    if (!gateOpen) await new Promise((resolve) => setTimeout(resolve, 100));
  }
  const guestFocusedBeforeKeys = await tab.playwright.evaluate(() => document.hasFocus());
  await tab.cua.keypress({ keys: ['a'] });
  await tab.cua.keypress({ keys: ['b'] });
  await tab.cua.keypress({ keys: ['Enter'] });
  await tab.playwright.evaluate(() => { document.getElementById('dialog').showModal(); });
  await tab.cua.keypress({ keys: ['Escape'] });
  const page = await tab.playwright.evaluate(() => ({ keys: window.__e2eKeys, submits: window.__e2eSubmits, value: document.getElementById('name').value, dialogOpen: document.getElementById('dialog').open }));
  const keypressOk = gateOpen && !guestFocusedBeforeKeys && page.value === 'ab' && page.submits === 1 && !page.dialogOpen && page.keys.join(',') === 'a,b,Enter,Escape';
  e2eResult = { marker: keypressOk ? 'E2E_BROWSER_USE_KEYPRESS_OK' : 'E2E_BROWSER_USE_KEYPRESS_FAILED', gateOpen, guestFocusedBeforeKeys, page };
} catch (error) {
  e2eResult = { marker: 'E2E_BROWSER_USE_KEYPRESS_FAILED', error: error instanceof Error ? (error.stack ?? error.message) : String(error) };
}
e2eResult;
